const L=(...a)=>'<ol>'+a.map(x=>'<li>'+x+'</li>').join('')+'</ol>';
const U=(...a)=>'<ul>'+a.map(x=>'<li>'+x+'</li>').join('')+'</ul>';
const TIP=t=>'<div class="htip">'+t+'</div>';
const WARN=t=>'<div class="hwarn">'+t+'</div>';
const FAQ=(q,a)=>'<details class="faq"><summary>'+q+'</summary><div>'+a+'</div></details>';

const HELP=[
{g:'Start here',id:'welcome',t:'What is Marchand?',tags:'about overview intro what',go:[['Open Models','models:library'],['Start coding','code']],h:`
<p>Marchand is a desktop app for AI models that run <b>on your own computer</b> through Ollama, plus optional cloud models such as Claude and Grok. It gives you:</p>
${U('<b>Chat</b>: talk to any model, like a normal chatbot.','<b>Code</b>: an AI assistant that works inside your project folder. It reads your files, changes them, runs your tests and fixes mistakes, asking your permission first.','<b>Plugins and connectors</b>: add commands, skills and tools (the same plug-in standard Claude Desktop uses).','<b>Models</b>: download, update and manage models. Ollama updates are one click.','<b>Teach</b>: a stronger AI (Claude or Grok) can teach your local model, and you can turn what it learned into a brand-new AI of your own.')}
${TIP('Everything runs on your computer. Nothing is sent anywhere unless you choose a cloud model or the teacher.')}`},
{g:'Start here',id:'quick',t:'Your first 10 minutes',tags:'quick start first install begin tutorial getting started',go:[['Open Models','models:library'],['Open Code','code']],h:`
<p>Follow these five steps once. After that you can ignore this page.</p>
${L('<b>Install Ollama</b> from ollama.com (the engine that runs models). Marchand shows a green dot at the bottom left when it is running.','Open the <b>Models</b> tab. Look at the line "Your PC" to see your memory and graphics card. Download a model that says <b>runs great</b>. For most gaming PCs that is <code>qwen2.5-coder:14b</code>; for a laptop use <code>qwen2.5-coder:7b</code> or <code>3b</code>.','Wait for the download (the bar fills). The model then appears in the picker at the top right.','Open the <b>Code</b> tab, press the folder button and choose your project folder.','Type what you want, for example <i>"find why the tests fail and fix it"</i>. Allow the steps it asks about. Read the diff before pressing Allow on an edit.')}
${TIP('Not sure which model? In Models the badge on each card tells you if it fits your PC: <b>runs great</b>, <b>runs (slower)</b> or <b>too big</b>.')}`},
{g:'Start here',id:'words',t:'Words explained simply',tags:'glossary terms token context model ollama mcp lora temperature vram',h:`
${U('<b>Model</b>: the AI "brain" file. Bigger usually means smarter but slower and needing more memory.','<b>Ollama</b>: the free program that runs models on your PC.','<b>Local vs cloud</b>: local runs on your PC for free and privately. Cloud (Claude, Grok...) runs on a company server, costs money and sends the text it reads to them.','<b>Token</b>: about three quarters of a word. Models read and write in tokens.','<b>Context / memory size</b>: how much text the model can keep in mind at once. Bigger needs more RAM.','<b>Temperature / style</b>: low = precise and repeatable, high = creative.','<b>Agent</b>: an AI that can use tools (read files, run commands) in a loop until a task is done.','<b>Tool</b>: one action the AI can take, like <code>read_file</code> or <code>run_command</code>.','<b>Plugin</b>: a bundle of slash commands, skills, tools and rules.','<b>Skill</b>: detailed instructions the AI loads only when needed.','<b>Connector / MCP</b>: a small program that gives the AI extra tools (GitHub, files, browser...). MCP is the standard Claude Desktop also uses.','<b>Teacher</b>: a stronger cloud AI that reviews your local model\'s work.','<b>Lesson</b>: a short rule the teacher wrote, added to every future prompt.','<b>Fine-tuning / LoRA</b>: changing the model\'s actual weights by training. Needs an NVIDIA graphics card.','<b>Quantization (Q4)</b>: shrinking a model so it fits in less memory.','<b>VRAM</b>: memory on your graphics card.')}`},

{g:'Using Marchand',id:'chat',t:'Chat tab',tags:'chat talk conversation images attach preview',go:[['Open Chat','chat']],h:`
<p>Pick a model at the top right and type. Press <b>Enter</b> to send, <b>Shift+Enter</b> for a new line.</p>
${U('<b>Attach files</b>: press the paperclip, drag files into the box, or paste an image. Text files are added to your message; images need a vision model (for example <code>llama3.2-vision</code>).','<b>Code blocks</b> have a <b>Copy</b> button. HTML and SVG blocks also get a <b>Preview</b> button that shows the page safely in a window.','<b>Stop</b>: press the red square (or Esc) while it is answering.','<b>Retry</b>: asks the same question again from the same starting point.')}`},
{g:'Using Marchand',id:'code',t:'Code tab: how the coding assistant works',tags:'code agent project edit files tests approval diff plan review verify stop undo',go:[['Open Code','code'],['Open Plugins','plugins:installed']],h:`
<p>Choose your project folder with the folder button. The assistant first looks around (file list, code map, git status, how tests are run, your instructions), then works in small steps:</p>
${L('It makes a <b>plan</b> (a checklist you can follow).','It <b>reads</b> and <b>searches</b> your code before changing anything.','It <b>edits</b> with exact replacements. Every edit shows a coloured <b>diff</b> (green = added, red = removed) and asks you to <b>Allow</b>, <b>Deny</b> or <b>Always allow</b>.','It <b>runs your tests/build</b> and reads the result. If something fails it tries again.','It will not finish a changed project until a check has passed. Before it finishes, a second <b>review pass</b> reads the diff looking for problems.')}
<h4>Making it better at your project</h4>
${U('Press <b>Instructions</b> and write rules for the project (how to build, how to test, style rules). They are saved as <code>MARCHAND.md</code> in your folder and read every time.','Use the <b>Files</b> button to browse the project and click a file to read it.','Type <code>/</code> for ready-made commands such as <code>/review</code> or <code>/tests</code> (install them in Plugins).')}
<h4>Undoing changes</h4>
<p>Marchand shows the diff of every change. If your project uses git (recommended), you can undo everything with <code>git checkout -- .</code> or review it with <code>git diff</code>. Commit before big tasks so you always have a safe point.</p>
${TIP('Tip: smaller, specific tasks work much better with local models than huge ones. "Add a --verbose flag to main.py" beats "rewrite the app".')}`},
{g:'Using Marchand',id:'approvals',t:'Approvals and safety switches',tags:'approve allow deny always auto permission safe',go:[['Open Settings','settings']],h:`
<p>Before it edits a file, writes a file, runs a command, calls a connector tool or asks the teacher, Marchand asks you. The card has three buttons:</p>
${U('<b>Deny</b>: nothing happens; the AI is told and tries something else.','<b>Allow</b>: just this one time.','<b>Always allow</b>: stop asking for the rest of this run.')}
<p>In Settings you can turn on <b>auto-approve</b> to skip all questions. Only do that on projects you have backed up with git.</p>
<p>Even with auto-approve, the AI can never touch files outside your project folder, and dangerous commands (like deleting the whole disk or force-pushing) are blocked.</p>`},
{g:'Using Marchand',id:'convos',t:'Conversations, search, export, shortcuts',tags:'history search rename delete export keyboard shortcuts ctrl',h:`
${U('Every conversation is saved on your computer (<code>~/.marchand/conversations</code>) and listed on the left.','<b>Search</b> box above the list filters by title. <b>Double-click</b> a title to rename it. The <b>x</b> deletes it.','<b>Export</b> (top right) saves the conversation as a Markdown file, including the diffs.','Shortcuts: <b>Ctrl+K</b> new conversation, <b>Ctrl+L</b> focus the message box, <b>Esc</b> stop, <b>Enter</b> send, <b>Shift+Enter</b> new line, <b>/</b> commands (arrows + Tab/Enter to choose).','Built-in commands: <code>/clear</code> starts a new conversation, <code>/plugins</code> opens Plugins.')}`},
{g:'Using Marchand',id:'settings',t:'Every setting explained',tags:'settings context temperature steps theme auto approve review instructions memory host',go:[['Open Settings','settings']],h:`
${U('<b>Ollama address</b>: where Ollama runs. Default <code>http://127.0.0.1:11434</code>. Change it to use Ollama on another computer, for example <code>http://192.168.1.20:11434</code> (Ollama must allow network access there).','<b>Context size</b>: how much the model can remember. 16384 is a good default. Bigger = remembers more but needs more RAM and is slower.','<b>Temperature</b>: 0.2 is precise (best for code). Raise it only for creative writing.','<b>Max agent steps</b>: how many actions the assistant may take per message before it pauses. 40 is plenty.','<b>Theme</b>: system, dark or light.','<b>Auto-approve</b>: skip all permission questions (use with care).','<b>Review pass</b>: after changes, a second look at the diff before finishing. Costs a little time, catches mistakes.','<b>Your own instructions</b>: text added to every conversation, like "answer in French" or "use tabs".')}`},

{g:'Models',id:'choose',t:'Which model should I download?',tags:'model choose pick best recommend ram vram gpu size qwen llama',go:[['Open the model library','models:library']],h:`
<p>The Models tab reads your computer and labels each model. As a rule of thumb:</p>
<table class="htable"><tr><th>Your PC</th><th>Good choice</th></tr>
<tr><td>Laptop, 8 GB RAM, no graphics card</td><td><code>qwen2.5-coder:3b</code></td></tr>
<tr><td>16 GB RAM or 8 GB graphics card</td><td><code>qwen2.5-coder:7b</code></td></tr>
<tr><td>12-16 GB graphics card</td><td><code>qwen2.5-coder:14b</code> (best balance)</td></tr>
<tr><td>24 GB graphics card or 32 GB RAM</td><td><code>qwen2.5-coder:32b</code>, <code>qwen3-coder:30b</code> or <code>devstral:24b</code></td></tr></table>
${U('Models marked <b>can edit files</b> support tools, which the Code tab needs. "Chat only" models still work in the Chat tab.','Bigger is smarter but slower. If answers take forever, pick the next size down.','Without a graphics card models run on the CPU, which works but is several times slower.')}`},
{g:'Models',id:'download',t:'Downloading, installing and deleting models',tags:'download pull install delete huggingface gguf remove disk',go:[['Open downloads','models:library'],['Installed models','models:installed']],h:`
${L('Open <b>Models &gt; Download models</b>.','Press <b>Download</b> on a card. A bar shows progress. Big models are several gigabytes.','Any other model: type its name in the box at the bottom, for example <code>llama3.3:70b</code>, or a Hugging Face model like <code>hf.co/user/repo:Q4_K_M</code>.')}
<p>Under <b>Installed</b> you can press <b>Use</b> (select it), <b>Info</b> (size, quantization, abilities) or <b>Delete</b> (frees the disk space).</p>`},
{g:'Models',id:'cloud',t:'Using Claude, Grok and other cloud models',tags:'cloud claude anthropic grok xai openai gemini openrouter deepseek groq mistral api key lm studio custom',go:[['Add a key','models:cloud']],h:`
<p>Cloud models are stronger than most local models but cost money and send the text they read to the company. Good for hard tasks and for <b>teaching</b> your local model.</p>
${L('Open <b>Models &gt; Cloud and local servers</b>.','Press <b>Get a key</b> on a provider and create an API key on their website (you need an account with billing).','Paste the key and press <b>Save and test</b>. You should see how many models were found.','The models now appear in the picker at the top right, grouped by company.')}
<p><b>Custom server</b> works with any OpenAI-compatible program: LM Studio (<code>http://127.0.0.1:1234/v1</code>), vLLM, llama.cpp server, text-generation-webui.</p>
${WARN('Your key is saved in plain text in <code>~/.marchand/settings.json</code> on your computer and only sent to that company. Do not share that file. Cloud usage is billed by the provider; Marchand does not show your spending.')}`},
{g:'Models',id:'update',t:'Updating Ollama',tags:'update ollama upgrade version latest install start',go:[['Open Ollama page','models:ollama']],h:`
${L('Open <b>Models &gt; Ollama</b>. It shows your version and the latest version.','If an update exists press <b>Update Ollama</b>. On Windows Marchand downloads the official installer and runs it silently; Ollama restarts by itself.','macOS: it runs <code>brew upgrade ollama</code> if you installed with Homebrew, otherwise it tells you to download the app. Linux: it shows the install command (needs sudo) unless Marchand runs as administrator.')}
<p>If Ollama is installed but not running, press <b>Start Ollama</b>. Marchand also checks for updates at startup (you can turn this off on the same page).</p>
${TIP('Update Ollama when a new model "needs a newer version" or when tool calling behaves badly.')}`},

{g:'Pictures and other apps',id:'images',t:'Make pictures (Images tab)',tags:'images pictures generate forge automatic1111 comfyui stable diffusion flux sdxl image art draw',go:[['Open Images','images'],['Find my apps','models:apps']],h:`
<p>The <b>Images</b> tab makes pictures with a generator running on your PC (<b>Forge</b>, <b>Automatic1111</b>, <b>SD.Next</b> or <b>ComfyUI</b>) or in the cloud (<b>OpenAI</b>, <b>Grok</b>, Together). Marchand does not contain a picture model itself: it talks to the one you installed, so you keep all your checkpoints and settings.</p>
${L('Start your generator first (see the next two guides).','Open <b>Images</b>. The top-left box shows which generators were found.','Write a <b>prompt</b> describing the picture. Press <b>Improve with AI</b> to let your chat model rewrite it into a detailed prompt.','Choose the size, checkpoint and sampler (they are read from the generator), then press <b>Generate</b>.','Click a picture in the gallery to enlarge it. From there you can <b>Download</b>, <b>Use in chat</b> (attach it to a message for a vision model), <b>Reuse settings</b> or <b>Delete</b>.')}
${U('<b>Start from a picture</b> (Forge/A1111 only): choose a file and drag <b>Change amount</b>. Low = small changes, high = a new picture.','<b>Seed</b> -1 gives a new picture each time. Reuse a seed to repeat a result.','<b>Stop</b> cancels the job on the generator too.','Pictures are saved in <code>~/.marchand/images</code> and listed in the gallery.','In any chat type <code>/image a red fox in the snow</code> to generate and show the picture right in the conversation.','In the Code tab, if a generator is available, the coding assistant gets a <code>generate_image</code> tool to create game art or icons straight into your project (it asks first).')}`},
{g:'Pictures and other apps',id:'forge',t:'Set up Forge / Automatic1111 / SD.Next',tags:'forge automatic1111 a1111 sd.next api webui-user.bat commandline args port 7860 setup',go:[['Open Images','images']],h:`
<p>These programs all share the same API. It is <b>off by default</b>.</p>
${L('Open the folder where Forge (or Automatic1111) is installed.','Right-click <code>webui-user.bat</code> &gt; Edit. Change the line to <code>set COMMANDLINE_ARGS=--api</code> (keep any other options you already have).','Save and start it with <code>webui-user.bat</code>. Wait for "Running on local URL: http://127.0.0.1:7860".','In Marchand open <b>Images</b>. Forge / A1111 should say <b>connected</b>. If your address differs press <b>Setup</b> and change it, then <b>Test</b>.')}
${TIP('Install checkpoints by putting .safetensors files in <code>models/Stable-diffusion</code>. Press Generate and Marchand lists them. Changing checkpoint makes Forge load it, which can take a minute.')}
${WARN('If Marchand says "API off" in Apps on this PC, Forge is running without <code>--api</code>. Close it and restart with the option.')}`},
{g:'Pictures and other apps',id:'comfy',t:'Set up ComfyUI (and custom workflows)',tags:'comfyui comfy workflow flux sdxl custom json api placeholders checkpoints port 8188',go:[['Open Images','images']],h:`
${L('Start ComfyUI normally (run_nvidia_gpu.bat, or the ComfyUI Desktop app). The default address is <code>http://127.0.0.1:8188</code> (the Desktop app may use port 8000: change it in Images &gt; Setup).','Put at least one model in <code>ComfyUI/models/checkpoints</code>.','Open <b>Images</b>. ComfyUI should say <b>connected</b>. Choose a checkpoint and press Generate: Marchand uses the standard text-to-image workflow.')}
<h4>Use your own workflow (FLUX, SDXL refiner, LoRA, upscale...)</h4>
${L('In ComfyUI open your workflow and choose <b>Save (API Format)</b> (turn on Dev mode options in ComfyUI settings if you do not see it).','In the saved JSON replace the values you want Marchand to control with placeholders: <code>"%prompt%"</code>, <code>"%negative%"</code>, <code>"%seed%"</code>, <code>"%steps%"</code>, <code>"%cfg%"</code>, <code>"%width%"</code>, <code>"%height%"</code>, <code>"%checkpoint%"</code>, <code>"%sampler%"</code>, <code>"%scheduler%"</code>, <code>"%count%"</code>.','Open <b>Images &gt; Setup</b>, paste it into <b>ComfyUI custom workflow</b> and Save. The workflow must end in a <b>SaveImage</b> node.')}
<p>Number placeholders must be the whole value, for example <code>"seed": "%seed%"</code>. Marchand turns them into real numbers.</p>`},
{g:'Pictures and other apps',id:'cloudimg',t:'Cloud pictures: OpenAI, Grok, Together',tags:'cloud images openai gpt-image dall-e grok xai together flux key',go:[['Add a key','models:cloud'],['Open Images','images']],h:`
<p>Add the key in <b>Models &gt; Cloud and local servers</b>. The provider then appears in the Images backend list as "(cloud)". Use <b>Setup</b> to choose the model name (for example <code>gpt-image-1</code> for OpenAI, <code>grok-2-image</code> for Grok). Cloud pictures cost money per image and the prompt leaves your computer.</p>
<p>Negative prompts, sampler and steps do not exist for cloud models; only the prompt and size are used.</p>`},
{g:'Pictures and other apps',id:'apps',t:'Apps on this PC and other model runners',tags:'apps scan detect lm studio jan kobold koboldcpp llama.cpp vllm text generation webui gpt4all localai invokeai fooocus open webui other software',go:[['Scan my PC','models:apps']],h:`
<p>Models &gt; <b>Apps on this PC</b> checks your own computer for AI programs that are running and lets you plug them in with one click:</p>
${U('<b>Model runners</b> with an OpenAI-style server: LM Studio, Jan, KoboldCpp, llama.cpp server, vLLM, text-generation-webui, GPT4All, LocalAI. Their models then show up in the model picker next to your Ollama models.','<b>Image generators</b>: Forge, Automatic1111, SD.Next, ComfyUI. InvokeAI, Fooocus-API and Open WebUI are detected and listed so you know they are running.')}
<p>You can also switch any of them on by hand in <b>Models &gt; Cloud and local servers &gt; Local servers on this PC</b>.</p>
${TIP('Marchand only ever looks at addresses on your own computer (127.0.0.1) and only when you press Scan.')}`},
{g:'Pictures and other apps',id:'prompts',t:'Writing good picture prompts',tags:'prompt tips negative style lighting quality how to write',h:`
${U('Say <b>what</b> (subject), <b>where</b> (setting), <b>how it looks</b> (style, lighting, camera) in that order, separated by commas.','Good: <i>portrait of an old fisherman, weathered face, golden hour, 85mm lens, shallow depth of field, photograph</i>.','Negative prompt (Forge/ComfyUI): things you do not want, like <i>blurry, low quality, extra fingers, watermark</i>.','FLUX and newer models prefer plain sentences. SD 1.5 and SDXL like comma-separated tags.','Not sure? Type a short idea and press <b>Improve with AI</b>.','Match the size to the model: 512 for SD 1.5, 1024 for SDXL and FLUX.')}`},
{g:'Claude and training',id:'claudesub',t:'Use Claude (Opus, Sonnet...) on your subscription',tags:'claude opus sonnet fable haiku subscription pro max claude code login effort low medium high xhigh max ultra',go:[['Open Chat','chat'],['Open Code','code']],h:`
<p>If <b>Claude Code</b> is installed on this PC and you are logged in, Marchand can use Claude on your own subscription. The models show up in the picker as <b>Claude (your subscription)</b>: Opus, Sonnet, Fable and Haiku (the "latest" entries always follow the newest version).</p>
${L('Install Claude Code from claude.ai/code (or <code>npm install -g @anthropic-ai/claude-code</code>).','Open a terminal, type <code>claude</code> once and log in with your Claude account. Close it.','Restart Marchand. Pick <b>Opus (latest)</b> in the model picker.','Next to the picker choose the <b>effort</b>: Low, Medium, High, Extra high or <b>Max (ultra)</b>. Higher effort thinks longer and uses more of your limits.')}
<h4>What happens</h4>
${U('<b>Chat tab</b>: a normal conversation with Claude (no file access). Follow-up messages continue the same Claude session.','<b>Code tab</b>: Claude works in your project folder with its own tools (read, edit, run commands, search). Every edit and command shows up as a Marchand approval card with a full diff, exactly like local models, unless auto-approve is on.','Your project rules from <b>Rules</b> (MARCHAND.md) and your own instructions are added for Claude too. Claude also reads CLAUDE.md files by itself.','Pictures and video frames you attach are sent to Claude, which can see them.')}
${WARN('Requests count against your Claude plan limits (see the side panel). Marchand only drives the official Claude Code program that you installed and logged into; it never reads or stores your Claude login.')}`},
{g:'Claude and training',id:'limits',t:'Your plan limits: session, weekly and extra usage',tags:'usage limit session weekly 5 hour seven day reset extra usage overage credit cost tokens',go:[['Open Chat','chat']],h:`
<p>The side panel (button <b>Panel</b>) shows <b>Claude plan usage</b> after your first Claude request:</p>
${U('<b>Session (5 hours)</b>: how much of your rolling 5-hour allowance is used, and when it resets.','<b>Weekly (7 days)</b>: how much of the weekly allowance is used, and when it resets. The bar turns orange at 75% and red at 90%.','<b>Extra usage</b>: whether extra (overage) usage is available or in use on your account.','<b>Today in Marchand</b>: how many Claude requests Marchand made today and their API-equivalent price. This is the price the same work would cost through the API; your subscription is not charged per request.')}
<p>Press <b>Refresh</b> to update the numbers; it sends one tiny Haiku request because Claude Code reports limits only together with a reply.</p>
${TIP('Prepaid "cloud credit" balances are not reported by Claude Code, so Marchand cannot show them. Check claude.ai/settings for the exact balance.')}`},
{g:'Claude and training',id:'amd',t:'AMD graphics cards (Radeon)',tags:'amd radeon rocm vulkan gpu directml zluda graphics nvidia',go:[['Open Models','models']],h:`
<p>Marchand detects AMD Radeon cards and shows them in the model list and under the chat.</p><ul><li><b>Models</b>: Ollama uses ROCm on supported Radeon cards (RX 6000/7000/9000 and many Pro cards). Other cards can try Ollama's experimental Vulkan mode (set <code>OLLAMA_VULKAN=1</code> and restart Ollama), or use LM Studio or KoboldCpp, which run on AMD through Vulkan. Without GPU support models still run on the CPU, only slower.</li><li><b>Pictures</b>: use the AMD builds of Forge / Automatic1111 (DirectML or ZLUDA) or ComfyUI with ROCm. Marchand links to them on the Images tab when it detects an AMD card.</li><li><b>Training</b>: everything works on AMD (Train with Claude, Marchand Coder, Reverser, lessons). Only GPU fine-tuning (Unsloth, in the GPU tab) needs an NVIDIA card.</li></ul>`},
{g:'Claude and training',id:'picker',t:'Choosing the AI under the chat (and adding more)',tags:'model picker toggle claude local cloud show more download add codex grok openai',go:[],h:`
<p>The pill under the message box shows the current AI. Click it to switch between <b>All / Claude / Local / Cloud</b>. It lists 6 models; <b>Show more models</b> opens the whole library with a Download button and an ollama.com link for each one, plus links to browse every Ollama and Hugging Face model.</p><p>Any AI you add appears there automatically: a key for Grok, OpenAI (its Codex models too), Gemini and others in Models &gt; Cloud and local servers; a local program in Training &gt; Add your model; Claude through Claude Code. Missing a program such as Forge, ComfyUI, Ollama or ffmpeg? Models &gt; Apps on this PC and the Images tab have download links.</p>`},
{g:'Claude and training',id:'tray',t:'The tray icon (hidden icons)',tags:'tray hidden icons notification area close quit background logo',go:[],h:`
<p>Marchand Studio puts its <b>M</b> logo in the Windows tray (the hidden icons arrow next to the clock). Closing the window keeps Marchand running there. Click the icon to open the window again; right-click it for <b>Open</b>, <b>Buy me a coffee</b> and <b>Quit</b>. Starting Marchand a second time just brings up the same window.</p>`},
{g:'Claude and training',id:'findagents',t:'Finding Claude and other AI agents on your PC',tags:'find search agent claude code codex gemini aider goose opencode install terminal desktop',go:[['Open Settings','settings']],h:`
<p>Marchand looks for <b>Claude Code</b> by itself every time it starts (normal install folders, Claude Desktop's bundled copy, the VS Code extension). If Claude is missing in the picker, press <b>Search this PC for AI agents</b> (Settings, the picker's Claude tab, or Models &gt; Apps on this PC). It finds Claude Code and lets you press <b>Use this one</b>. It also reports Codex CLI, Gemini CLI, Aider, Goose and opencode, with install links for the ones that are missing.</p><p><b>Claude Desktop alone is not enough.</b> In Claude Desktop open the Claude Code environments list and press <b>Install</b> next to <b>Terminal</b> (or go to claude.ai/code), then run <code>claude</code> once in a terminal to log in.</p><p class="meta">Honest note: Marchand can drive Claude Code. The other agents are detected and linked, but you use their models through a key in the picker.</p>`},
{g:'Claude and training',id:'license',t:'License: what you may and may not do',tags:'license polyform noncommercial open source fork credit commercial trademark coffee',go:[],h:`
<p>Marchand Studio is released under the <b>PolyForm Noncommercial License 1.0.0</b>. You may use it, read the code, change it and share it for <b>non-commercial</b> purposes. You must keep the copyright and <i>Required Notice</i> lines (in the LICENSE and NOTICE files) with any copy. Selling it or using it commercially needs the author's permission. The name <b>Marchand Studio</b> and the M logo are not part of the license: a fork must use its own name and logo and say it is based on Marchand Studio (see TRADEMARK.md).</p>`},
{g:'Claude and training',id:'plusmenu',t:'The + menu next to the message box',tags:'plus add files photos folder slash commands connectors plugins ctrl+u enter send',go:[],h:`
<p>Click <b>+</b> left of the message box:</p><ul><li><b>Add files or photos</b> (Ctrl+U): attach pictures, videos and text files.</li><li><b>Add folder</b> (Code only): lets the AI read another folder besides your project.</li><li><b>Slash commands</b>: opens the command list from your plugins.</li><li><b>Connectors</b>: switch your MCP connectors on or off, or open the full manager.</li><li><b>Plugins</b> (Code only): switch plugins on or off.</li><li><b>Send with</b>: choose Enter or Ctrl+Enter to send.</li></ul>`},
{g:'Claude and training',id:'panel',t:'The side panel (environment, context, outputs, changes, files)',tags:'panel sidebar environment context outputs changes files commit diff branch store upload',go:[['Open Code','code']],h:`
${U('<b>Environment</b>: the model (and effort), the project folder (click to change) and the git branch.','<b>Context</b>: how full the model\'s memory is for this conversation. Start a new conversation when it gets high.','<b>Claude plan usage</b>: your session and weekly limits (see the previous topic).','<b>Outputs</b>: files the AI created and pictures it generated. Click one to open it.','<b>Changes</b>: lines added and removed in this conversation. <b>View diff</b> shows everything; <b>Commit</b> saves all changes in git with your message.','<b>Files</b>: everything you attached or uploaded is kept with the conversation (in ~/.marchand/files). Click a file to attach it again. <b>Upload files</b> adds more.','<b>Project files</b>: browse and read files in the Code tab.')}
<p>Click a section title to fold it. The panel remembers what you folded.</p>`},
{g:'Claude and training',id:'vision',t:'Pictures and videos for any AI',tags:'image picture photo screenshot video mp4 frames vision see analyze ffmpeg',go:[['Open Settings','settings']],h:`
${L('Attach with the paperclip, drag and drop, or paste a screenshot.','<b>Videos</b> (mp4, mov, webm, mkv, gif...) are turned into 6 frames spread over the clip plus a note with their timestamps, so any vision AI can analyse what happens. This needs <b>ffmpeg</b> (Windows: <code>winget install ffmpeg</code>).','Claude, GPT, Gemini and Grok models see images directly. Local Ollama models that can see (llama3.2-vision, gemma3, qwen2.5vl, minicpm-v, llava) also get them directly.','For a local AI that cannot see (for example your trained coder), choose a <b>Vision helper</b> in Settings. Marchand then asks the helper to describe the pictures and gives the description to your AI. That is how a trained coder can still work from screenshots and videos.')}`},
{g:'Claude and training',id:'languages',t:'Training for every programming language',tags:'languages python javascript typescript c cpp c++ csharp c# java go rust php ruby perl lua bash sql kotlin swift powershell all languages curriculum toolchain install',go:[['Open Train with Claude','training:quick'],['Open Advanced','training:train']],h:`
<p>Marchand's curriculum has <b>62 verified tasks</b>. Every task has real tests and a reference solution, and every one fails before the fix and passes after it.</p>
<table class="htable"><tr><th>Group</th><th>Tasks</th><th>What your PC needs</th></tr>
<tr><td>Python</td><td>25</td><td>Python (you already have it)</td></tr>
<tr><td>JavaScript, TypeScript</td><td>2 + 2</td><td>Node.js 22.6+ (TypeScript runs with <code>--experimental-strip-types</code>)</td></tr>
<tr><td>C, C++</td><td>2 + 2</td><td>gcc / g++ (Windows: MSYS2 or MinGW)</td></tr>
<tr><td>C#</td><td>2</td><td>.NET SDK (the project file adapts to your SDK version)</td></tr>
<tr><td>Java</td><td>2</td><td>JDK (javac + java)</td></tr>
<tr><td>Go, Rust</td><td>2 + 2</td><td>go, rustc</td></tr>
<tr><td>PHP, Ruby, Perl, Lua</td><td>2 each</td><td>php (with PDO SQLite), ruby, perl, lua</td></tr>
<tr><td>Bash</td><td>2</td><td>bash (Windows: Git Bash or WSL)</td></tr>
<tr><td>SQL</td><td>2</td><td>nothing extra (runs on Python's SQLite)</td></tr>
<tr><td>Reverse engineering</td><td>9</td><td>Python (one task also needs Node.js)</td></tr></table>
${U('Marchand checks your PC. Languages whose tools are missing are greyed out with the reason (for example "needs go") and are skipped automatically; install the tool to unlock them.','In <b>Train with Claude</b> choose <b>Every language</b> (1 task each), <b>Reverse engineering</b>, <b>Pick languages</b> (tick any), or <b>Everything my PC can run</b>.','Lessons are tagged by language, so a Rust lesson is only given to the AI when it works on Rust. Language guides (Python, JavaScript, TypeScript, C, C++, C#, Java, Kotlin, Go, Rust, PHP, Ruby, Perl, Lua, Bash, SQL, Swift, PowerShell) are loaded automatically for the languages found in your project.','<b>Marchand Coder</b> is built with all of it: a persona fluent in all these languages, 90 expert lessons (about 40 general plus language-specific ones), the reverse-engineering method and worked examples in several languages.')}
${TIP('Kotlin, Swift and PowerShell have guides and lessons but no graded tasks yet because their compilers are not widely installed. You can add your own graded tasks for any language in Training &gt; Your tasks.')}`},
{g:'Claude and training',id:'reversing',t:'Reverse engineering training (defensive and educational)',tags:'reverse engineering disassemble assembly binary file format protocol deobfuscate xor decode analyse unknown',go:[['Train on reverse engineering','training:quick']],h:`
<p>The nine reverse-engineering tasks teach your AI to work out how something works from evidence, which is the core skill behind understanding legacy files, devices and compiled code:</p>
${U('<b>Unknown file format</b>: hex dumps of game saves, work out the layout and write a parser.','<b>Assembly to code</b>: read compiler output (x86-64) and rewrite the function.','<b>Deobfuscate JavaScript</b>: turn machine-obfuscated code into readable code and prove it behaves the same.','<b>Known plaintext</b>: recover a repeating XOR key from a known header.','<b>Black box</b>: infer a hidden function from input/output samples.','<b>Layered encodings</b>: peel hex, base64, zlib and JSON layers automatically.','<b>Device protocol</b>: decode packets from a capture, including the checksum.','<b>Unknown database</b>: explore an SQLite file with its own metadata.','<b>Bytecode VM</b>: read an interpreter and write a disassembler for it.')}
<p>The method it learns (observe the samples, hypothesise, test on every sample, write a parser and tests) is in the <b>reverse engineering guide</b> that Marchand gives every AI. It applies to files, protocols and code you are allowed to analyse: your own data, training and CTF material, interoperability and sandboxed analysis.</p>
${WARN('Marchand does not train or help with cracking licences, bypassing DRM or anti-cheat, or writing malware. The lessons and guide say so explicitly.')}`},
{g:'Claude and training',id:'quicktrain',t:'Train your AI with Claude (one button)',tags:'train teach claude one button quick save ai student teacher',go:[['Open Train with Claude','training:quick']],h:`
${L('Open <b>Training &gt; Train with Claude</b>.','<b>Your AI</b>: the local model to train (for example Marchand Coder or qwen2.5-coder).','<b>Teacher</b>: Claude on your subscription is chosen automatically when Claude Code is installed. Pick another model if you prefer.','<b>Teacher effort</b>: High is a good balance; Max (ultra) teaches best and uses the most of your limits.','<b>How long</b>: Quick (6 Python tasks), Every language (1 task each), Reverse engineering (9), pick languages yourself, or everything your PC can run. Press <b>Start teaching</b>.','Watch the live report: each task shows pass or fail, how many steps, and whether Claude demonstrated the solution. Round 2 re-tests your AI after the lessons.','When it finishes, type a name and press <b>Save AI</b>. Then <b>Use it now</b>.')}
${TIP('Run it again later: lessons accumulate, and each run adds verified examples. Save under the same name to update your AI.')}`},
{g:'Claude and training',id:'howtrain',t:'How training works (and what it can achieve)',tags:'training how works rounds lessons demonstrations curriculum tests sandbox improvement honest',go:[['Open Advanced training','training:train']],h:`
<p>Marchand ships with <b>62 coding tasks in 16 groups</b> (Python and 14 other languages plus reverse engineering): bug fixes, features, security, performance and multi-file work. Every task has real tests and a reference solution; all of them fail before the fix and pass after it, so the score is measured, not guessed.</p>
${L('<b>Attempt</b>: your AI gets the task in a fresh sandbox copy and works with its normal tools.','<b>Grade</b>: Marchand restores the original tests (so they cannot be "cheated") and runs them.','<b>Review</b>: when it fails, the teacher reads the whole transcript and test output, and writes short general lessons.','<b>Demonstrate</b>: the teacher solves the same task; if its solution passes, the transcript is saved as a training example in Marchand\'s tool format. Without a teacher, the built-in reference solution is used.','<b>Re-test</b>: the last round measures your AI again with the new lessons, so you see the before/after pass rate.','<b>Condense</b>: at the end the teacher merges the lessons into 25 strong rules (your own rules are kept).')}
<h4>Advanced options</h4>
${U('Rounds 1 to 3, max steps per task, which tasks, whether to keep successful attempts as examples, the Marchand Coder persona, and a name to save the AI automatically.','<b>Your tasks</b>: add your own projects with a test command; each attempt runs in a copy, never on your original.')}
${WARN('What this changes: the AI\'s instructions (lessons, persona) and the examples it is shown. It does not change the model\'s weights; only GPU fine-tuning does that. A small model will improve its habits but will not become Opus.')}`},
{g:'Claude and training',id:'teachctx',t:'How the teacher knows it is teaching another AI',tags:'teacher context prompt teaching another ai student instructions',h:`
<p>Every request to a teacher (Claude, Grok or any model) starts with a fixed briefing. It explains that the teacher is training a smaller local model that cannot see the conversation, that the student learns only from short general rules and from worked examples, which tools the student has, and how to teach well: judge by real test results, name the single most important mistake, write habits not project trivia, be concrete and honest.</p>
<p>When the teacher <b>demonstrates</b> a solution, it gets a second briefing: work in small, copyable steps (run the failing test, read, make the smallest edit, re-test, summarise), avoid clever shortcuts and never touch the tests. Its transcript is converted to Marchand's own tool names so your AI can learn from it directly.</p>`},
{g:'Claude and training',id:'coder',t:'Marchand Coder: the pre-trained coding AI',tags:'marchand coder pretrained install benchmark best ollama model code like claude',go:[['Open Marchand Coder','training:coder']],h:`
${L('Open <b>Training &gt; Marchand Coder</b>. The recommended base model is picked from your graphics card and memory.','Press <b>Install Marchand Coder</b>. It downloads the base model if needed, adds 90 expert coding rules (general and per language), the reverse-engineering method and verified worked examples in several languages, and builds the model <code>marchand-coder</code>.','Press <b>Benchmark it</b> to measure it on 10 tasks without any help.','Then improve it with <b>Train with Claude</b> and press Save AI with the same name.')}
${TIP('Marchand Coder copies how a careful senior engineer (and Claude) works: read first, small edits, tests after every change, root causes, honest summaries. It runs fully offline once installed.')}`},
{g:'Claude and training',id:'gpu',t:'GPU fine-tuning (real weight training)',tags:'fine tune finetune lora unsloth gpu nvidia gguf weights train model',go:[['Open GPU page','training:gpu']],h:`
<p>With an NVIDIA graphics card, Marchand can turn your saved examples into a genuinely retrained model:</p>
${L('Collect examples: run training sessions (teacher demonstrations and successful attempts are saved automatically) and use thumbs up. 10 is the minimum; 100+ gives real results.','Install the training packages once: <code>python -m pip install unsloth trl datasets</code> (the GPU page shows the exact command for your Python).','Open <b>Training &gt; GPU</b>, choose the base model (the page shows how much video memory each needs), the number of epochs, and a name.','Press <b>Start fine-tuning</b>. The log shows the training loss. At the end Marchand exports a GGUF file and adds it to Ollama as your new model.')}
${WARN('Fine-tuning needs a CUDA-capable NVIDIA GPU and can take from minutes to hours. The page checks your hardware and packages before starting. If something fails, the log shows the exact error.')}`},
{g:'Teach an AI',id:'teachintro',t:'Teaching an AI: what it can and cannot do',tags:'teach train learn how it works overview expectations lessons fine tune',go:[['Open Teach','teach:setup']],h:`
<p>Marchand teaches your local model in four ways. The first three work immediately on any PC.</p>
<table class="htable"><tr><th>Way</th><th>What happens</th><th>Needs</th></tr>
<tr><td><b>Lessons</b></td><td>A teacher (Claude or Grok) grades your local model's work and writes short rules. They are added to every future prompt.</td><td>A cloud key</td></tr>
<tr><td><b>Ask the teacher</b></td><td>When stuck, your local model asks the teacher for advice (you approve each question).</td><td>A cloud key</td></tr>
<tr><td><b>Examples</b></td><td>Good finished tasks (yours or the teacher's) are saved so your AI can copy their style, or be exported to train it.</td><td>Nothing</td></tr>
<tr><td><b>Fine-tuning</b></td><td>Actually changes the model's weights using the saved examples.</td><td>NVIDIA GPU, advanced</td></tr></table>
${WARN('Be realistic: teaching improves <i>habits</i> (reading before editing, running tests, avoiding past mistakes). It does not turn a small model into Claude. A 14B model taught well is noticeably better, but it is still a 14B model.')}`},
{g:'Teach an AI',id:'teachguide',t:'Guide: teach your AI step by step',tags:'teach guide tutorial step by step how to train lessons teacher claude grok',go:[['1. Add a cloud key','models:cloud'],['2. Choose the teacher','teach:setup'],['3. See the lessons','teach:lessons']],h:`
<p>This is the full routine. Do it for a few real tasks and your AI improves each time.</p>
${L('<b>Add a teacher key.</b> Models &gt; Cloud and local servers: add a Claude or Grok key and press Save and test.','<b>Choose the teacher.</b> Training &gt; Teacher: pick the cloud model (a strong one like a Claude Opus/Sonnet or Grok 4 works best) and press Save.','<b>Give your local model a real task.</b> Select your local model, open Code, choose a project, and ask for something specific (fix a bug, add a feature, write tests).','<b>Let it finish.</b> Allow or deny its steps. Do not fix its mistakes yourself yet: the mistakes are what the teacher learns from.','<b>Press Teach</b> under its final answer. The teacher reads the whole transcript and shows a score, the mistakes it made, a better approach, and the <b>lessons</b> it saved.','<b>Check the lessons.</b> Training &gt; Lessons: turn off or edit any lesson you disagree with. Good lessons are short and general, like "Run the tests after every edit".','<b>Repeat with different tasks</b> (5 to 10 tasks is a good start). Lessons for the same mistake are not duplicated.','<b>Save the good ones.</b> When your AI does a task well, press the thumbs up. Those become examples.','<b>Create your AI</b> (next guide) to lock everything in.')}
${TIP('Cost tip: one Teach click sends one transcript (roughly 3,000 to 8,000 tokens) to the teacher, usually a few cents. Teach after finished tasks, not after every message.')}
${TIP('Make the teacher cheaper: pick a smaller cloud model for the Teach step, and keep the stronger one for hard coding tasks.')}`},
{g:'Teach an AI',id:'lessons',t:'Lessons: editing and writing your own',tags:'lessons rules edit write add delete toggle',go:[['Open lessons','teach:lessons']],h:`
<p>Lessons are plain rules added to every code session (the first ones matching your project language are used, up to about 1,800 characters).</p>
${U('Add your own: type a rule in the box, for example <i>"Never edit files in the vendor folder."</i> and press Add.','Turn a lesson off with its switch without deleting it. Delete the wrong ones.','Good lessons are short (under 25 words), general and actionable. Bad lessons are about one specific file.')}`},
{g:'Teach an AI',id:'askteacher',t:'Ask the teacher when stuck',tags:'ask teacher stuck help escalate cloud',go:[['Choose a teacher','teach:setup']],h:`
<p>When a teacher is selected, your local model gets an <code>ask_teacher</code> tool. It is told to use it only after two failed attempts. Each question shows an approval card that says which cloud model will receive it, so you stay in control of cost and privacy.</p>
<p>You can also turn on <b>Use the teacher for the review pass</b> (Training &gt; Teacher) so a stronger model double-checks every change before it finishes.</p>`},
{g:'Teach an AI',id:'examples',t:'Examples, thumbs and datasets',tags:'examples thumbs up down dataset export jsonl fine tune lora unsloth gpu train',go:[['Open Examples','teach:examples']],h:`
${U('A <b>thumbs up</b> saves the whole conversation as a good example. <b>Thumbs down</b> saves a bad example (never exported).','You can also run a task with a Claude or Grok model as the coder and thumbs-up it: that is a "gold" example of how a strong AI solves it.','Examples can be copied into your AI as sample conversations (see Create your AI).')}
<h4>Real fine-tuning (advanced)</h4>
<p>Training &gt; Examples &gt; <b>Export dataset</b> gives two files: <code>marchand_dataset.jsonl</code> (training data with tool calls) and <code>train_lora_unsloth.py</code> (a LoRA training script).</p>
${L('You need an NVIDIA graphics card (8 GB+ for a 7B model), Python and <code>pip install unsloth trl datasets</code>.','Collect at least 50 to 100 good examples for a visible effect.','Run the script. It produces a GGUF file. Create an Ollama model from it with a Modelfile line <code>FROM ./marchand-gguf/yourfile.gguf</code> and <code>ollama create my-tuned -f Modelfile</code>.')}
${WARN('The training script is a starting template that has not been run on your hardware. Library versions change often, so expect to adjust it. Lessons plus Create your AI give most of the benefit with none of this work.')}`},

{g:'Create your AI',id:'createguide',t:'Guide: create your own AI after teaching',tags:'create new ai model bake persona build rebuild my ais own',go:[['Open Create your AI','teach:build']],h:`
<p>"Create your AI" builds a <b>new Ollama model</b> from one you already have, with your teaching built in. It is fast (seconds) and uses almost no extra disk space.</p>
${L('Open <b>Training &gt; My AIs</b>.','<b>Name</b>: for example <code>my-cpp-coder</code> (lowercase letters, numbers, dashes).','<b>Start from</b>: your best local coder. The new AI inherits its intelligence.','<b>What is it for?</b> One or two sentences describing the AI\'s role, like <i>"You help me maintain a C++ game server. Be careful with threading and always run the build."</i>','<b>Build in my lessons</b>: keep this ticked so every lesson becomes part of the AI.','<b>Include my best examples</b>: choose how many thumbs-up conversations to show it as samples (0 to 5; more examples use more memory).','<b>Style</b>: Precise for code, Creative for writing. <b>Memory</b>: Normal (16K) is a good default.','Press <b>Create my AI</b>. When it says ready, press <b>Use it now</b>.')}
<h4>After creating it</h4>
${U('It appears in the model picker (top right) and under <b>My AIs</b>.','Because it is a normal Ollama model, you can also use it in other Ollama apps by its name.','Teach it more later, then press <b>Rebuild with latest lessons</b> on its card. Same name, newer knowledge.','<b>Delete</b> removes the AI from your computer; your lessons and examples stay.')}
${TIP('Test it: give your new AI the same task your old model failed at. If it still fails the same way, press Teach again and the teacher will write a sharper lesson.')}`},
{g:'Create your AI',id:'createwhat',t:'What exactly gets built into my AI?',tags:'what is inside system prompt modelfile lessons persona examples weights',h:`
<p>The new model is your base model plus a built-in <b>system prompt</b> made of:</p>
${U('Marchand\'s engineering method (read first, small edits, always verify, finish honestly).','How to use the coding tools correctly.','A debugging method.','Your role text (if you wrote one).','Your active lessons (up to about 3,000 characters).','Up to five example conversations (optional).')}
<p>Its <b>weights</b> (the actual intelligence) are not changed; that only happens with fine-tuning (see Examples and datasets). That is why creating an AI is instant and safe: you can always delete it and the base model is untouched.</p>`},

{g:'Plugins and connectors',id:'plugins',t:'Plugins: install, turn on and off',tags:'plugin install enable disable uninstall slash command skills tools bundled discover',go:[['Open Plugins','plugins:installed'],['Discover plugins','plugins:discover']],h:`
<p>A plugin can add <b>slash commands</b>, <b>skills</b>, <b>tools</b> and <b>rules</b>. Plugins &gt; Discover lists the included ones:</p>
${U('<b>code-review</b>: <code>/review</code> your uncommitted changes.','<b>test-writer</b>: <code>/tests</code> and <code>/fix-tests</code>.','<b>debugger</b>: <code>/debug</code> an error systematically.','<b>git-helper</b>: <code>/commit-message</code>, <code>/pr-description</code>, <code>/changelog</code> and git tools.','<b>docs-writer</b>: <code>/explain</code>, <code>/docs</code>, <code>/init</code> (writes a project guide).','<b>security-audit</b>: <code>/audit</code>.','<b>refactor-assistant</b>: <code>/refactor</code>.','<b>python-tools</b>: pytest, ruff and mypy as tools. <b>shell-tools</b>: fetch a web page.')}
<p>Press <b>Install</b>, then use the switch in the Plugins tab to turn one off without removing it. Type <code>/</code> in the message box to use a command; text after the command replaces <code>{args}</code> in its prompt, e.g. <code>/tests src/utils.py</code>.</p>
<p>You can also install your own from a folder or a .zip file (Plugins &gt; Discover &gt; Install your own).</p>`},
{g:'Plugins and connectors',id:'makeplugin',t:'Make your own plugin',tags:'create plugin json command skill tool rules custom manifest',go:[['Create a plugin','plugins:create']],h:`
<p><b>Easy way:</b> Plugins &gt; Create. Give it a name, rules for the AI and (optionally) one slash command.</p>
<p><b>Full way:</b> a plugin is a folder in <code>~/.marchand/plugins/NAME</code> with a <code>plugin.json</code>:</p>
<pre class="hcode">{
  "name": "my-plugin",
  "description": "What it does",
  "system": "Rules the AI always follows. Use tabs. Prefer small functions.",
  "commands": [
    {"name": "ship", "description": "Test then commit message",
     "prompt": "Run the tests, then write a commit message. {args}"}
  ],
  "skills": [
    {"name": "style", "description": "Our coding style", "file": "skills/style.md"}
  ],
  "tools": [
    {"name": "run_lint", "description": "Lint a path",
     "parameters": {"path": "string"}, "command": "ruff check {path}"}
  ]
}</pre>
${U('<b>commands</b>: slash commands. <code>{args}</code> is what you type after the command.','<b>skills</b>: longer instructions in a .md file. The AI sees only the name and description, and loads the full text when relevant.','<b>tools</b>: a shell command the AI can call. <code>{path}</code> is replaced with the value it gives (safely quoted). Tools ask your permission like any command.')}`},
{g:'Plugins and connectors',id:'mcp',t:'Connectors (MCP): GitHub, files, browser...',tags:'connector mcp model context protocol github filesystem browser playwright fetch server tools',go:[['Open Connectors','plugins:connectors']],h:`
<p>Connectors are small programs that give the AI extra tools. Marchand speaks MCP, the same standard Claude Desktop uses, so thousands of existing connectors work.</p>
${L('Plugins &gt; Connectors (MCP).','Press a preset (filesystem, fetch, git, github, memory, playwright, sqlite...) to fill in the form, or type your own command.','Edit the command if needed (for example the folder path for filesystem), add environment variables such as a GitHub token, and press <b>Add connector</b>.','Press <b>Test</b>. You should see the list of tools it offers.','Use the code tab as usual: the AI can now call those tools (each call asks permission).')}
${WARN('Most connectors are started with <code>npx</code> or <code>uvx</code>, so you need Node.js (nodejs.org) or uv installed. A connector runs on your computer with your permissions: only add ones you trust.')}`},
{g:'Plugins and connectors',id:'claude',t:'Connect Claude Desktop (both directions)',tags:'claude desktop connect import config mcp link anthropic',go:[['Open Claude Desktop page','plugins:claude']],h:`
<h4>1. Bring your Claude Desktop connectors into Marchand</h4>
${L('Plugins &gt; Claude Desktop. Marchand finds Claude Desktop\'s config file automatically (or paste its path).','Tick the connectors you want and press <b>Import selected</b>.','Check them in the Connectors tab with <b>Test</b>.')}
<h4>2. Let Claude Desktop use your local models</h4>
${L('Press <b>Connect Claude Desktop</b>. Your config file is backed up first.','Restart Claude Desktop.','In Claude Desktop you can now ask things like <i>"Use my local model to summarise this private text"</i> or <i>"Ask my local coding agent to add tests to C:\\\\projects\\\\app"</i>.')}
<p>Tools Claude gets: <b>list_local_models</b>, <b>ask_local_model</b> (private and free), <b>run_local_coding_agent</b> (a local model edits a project folder). Press <b>Disconnect</b> any time to remove it. Marchand does not need to be open; Claude Desktop starts it when needed, but Ollama must be running.</p>
${TIP('Claude Desktop asks you before using a tool, and <code>run_local_coding_agent</code> edits files without further questions inside the folder you named, so only point it at projects under git.')}`},

{g:'Safety and privacy',id:'privacy',t:'What stays on my PC and what leaves it',tags:'privacy safe secure data cloud send keys security',h:`
<table class="htable"><tr><th>Situation</th><th>Data sent out</th></tr>
<tr><td>Local model (Ollama)</td><td><b>Nothing</b>. Everything stays on your computer.</td></tr>
<tr><td>Cloud model as your assistant</td><td>Your messages and the file contents it reads go to that company.</td></tr>
<tr><td>Teach button</td><td>The transcript of that conversation (including code it read or wrote) goes to the teacher company.</td></tr>
<tr><td>ask_teacher tool</td><td>The question and recent conversation, only after you approve.</td></tr>
<tr><td>Model downloads, update check</td><td>Requests to ollama.com and github.com.</td></tr></table>
<h4>Built-in protections</h4>
${U('Marchand listens on your own computer only and rejects requests that do not carry its secret session token, so websites cannot control it.','File access is limited to the project folder. Destructive commands are blocked.','Edits and commands need your approval unless you switch auto-approve on.','API keys are only sent to their own provider and are hidden in the screen (only the last four characters show).','Plugins, connectors and commands run programs on your PC: install only what you trust.')}`},

{g:'Help and fixes',id:'trouble',t:'Error messages and what to do',tags:'error problem fix troubleshoot message not working cannot reach tools support forbidden 401 429 connector blocked',h:`
<table class="htable"><tr><th>You see</th><th>What it means and the fix</th></tr>
<tr><td>"Cannot reach Ollama"</td><td>Ollama is not running. Models &gt; Ollama &gt; <b>Start Ollama</b>, or open the Ollama app. Check the address in Settings.</td></tr>
<tr><td>"does not support tools"</td><td>That model cannot edit files. Use a model marked <b>can edit files</b> (such as qwen2.5-coder) in the Code tab. It still works in Chat.</td></tr>
<tr><td>"No API key for ..."</td><td>Add the key in Models &gt; Cloud and local servers.</td></tr>
<tr><td>"HTTP 401" from a cloud model</td><td>The key is wrong, expired or has no billing. Create a new one and Save and test.</td></tr>
<tr><td>"HTTP 429"</td><td>Rate limit or no credit left. Wait a minute or add credit.</td></tr>
<tr><td>"Project folder not found"</td><td>Choose the folder again with the folder button.</td></tr>
<tr><td>"path is outside the project"</td><td>By design: the AI may only touch files in your project folder.</td></tr>
<tr><td>"command blocked for safety"</td><td>By design: that command could destroy data. Run it yourself if you really need it.</td></tr>
<tr><td>"old text not found" (during an edit)</td><td>The AI mis-copied the code. It re-reads the file and retries by itself; if it loops, pick a bigger model.</td></tr>
<tr><td>"Not finished: you changed files but did not run a passing check"</td><td>Normal: Marchand makes the AI test its work before finishing.</td></tr>
<tr><td>"Connector X unavailable"</td><td>The connector did not start. Is Node.js (npx) or uv (uvx) installed? Check the command in Plugins &gt; Connectors &gt; Test.</td></tr>
<tr><td>"forbidden" or the page shows nothing</td><td>You opened an old page from before a restart. Close it and start Marchand again from its icon.</td></tr>
<tr><td>Answers are very slow</td><td>The model is too big for your PC. Pick a smaller one, or lower the memory size in Settings.</td></tr>
<tr><td>It keeps repeating itself</td><td>Press Stop, then make the request more specific, or use a stronger model. Local models under 7B struggle with agent work.</td></tr></table>`},
{g:'Help and fixes',id:'install',t:'Install, shortcut and window problems',tags:'install shortcut desktop window python pywebview edge chrome start icon windows mac linux uninstall',h:`
${L('Install <b>Python 3.9+</b> from python.org (tick "Add Python to PATH") and <b>Ollama</b> from ollama.com.','Double-click <b>Install-Desktop-App.bat</b> once. It installs the window component and puts a <b>Marchand</b> icon on your Desktop and in the Start menu.','Open Marchand from that icon.')}
<p>Marchand opens in its own window. If the window component cannot be installed it uses Microsoft Edge or Google Chrome in a borderless "app" window instead; if neither exists it opens your normal browser. Use <b>Marchand-Debug.bat</b> if nothing appears: it shows the error text.</p>
${U('<b>Uninstall</b>: delete the Marchand folder and the shortcut. Your data is in <code>~/.marchand</code> (conversations, lessons, plugins, settings); delete it too for a full reset.','<b>Antivirus / SmartScreen</b> may warn about a script you downloaded; Marchand is plain Python text you can read.','Port 8765 busy: Marchand automatically picks another free port.')}`},

{g:'Help and fixes',id:'faq',t:'Frequently asked questions',tags:'faq questions answers how can i why does cost free offline gpu undo reset slow',h:
FAQ('Why does the Images tab say no generator found?','Start Forge (with <code>--api</code>) or ComfyUI first, then reopen Images. If it runs on another port, use Setup to change the address. Models &gt; Apps on this PC can find it.')+
FAQ('Forge says the API is off. What do I do?','Edit <code>webui-user.bat</code>, set <code>COMMANDLINE_ARGS=--api</code> and restart Forge.')+
FAQ('ComfyUI says it finished but returned no images.','A custom workflow must end in a <b>SaveImage</b> node. Use the built-in workflow by clearing the custom workflow box in Setup.')+
FAQ('Generation is stuck at 0%.','The first picture after starting loads the checkpoint into the graphics card; that can take a minute. Check the generator\'s own window for errors (usually out of video memory: lower the size).')+
FAQ('Can I use my own LoRAs or ControlNet?','Yes: in Forge add the LoRA to the prompt as <code>&lt;lora:name:0.8&gt;</code>. For anything more complex build a workflow in ComfyUI and paste it into Setup.')+
FAQ('Can the coding assistant make game art?','Yes. When a generator is running, the Code tab can call <code>generate_image</code> and save PNG files into your project (it asks first).')+
FAQ('Which extra programs does Marchand support?','Chat models: Ollama, LM Studio, Jan, KoboldCpp, llama.cpp, vLLM, text-generation-webui, GPT4All, LocalAI and any OpenAI-compatible server. Pictures: Forge, Automatic1111, SD.Next, ComfyUI, OpenAI, Grok and Together. Plus Claude, Grok, Gemini, DeepSeek, Groq, Mistral, OpenRouter, Cerebras, Fireworks, NVIDIA, Hugging Face, Perplexity, Cohere and GitHub Models in the cloud.')+
FAQ('Is my local AI now a copy of Opus?','No, and nothing can make it one: Opus is far larger. Training gives your local model Claude-like habits (careful, tested, honest), lessons from its own mistakes and verified examples. For Opus itself, pick it in the model picker on your subscription.')+
FAQ('Does training use my Claude limits?','Yes, when Claude is the teacher. Each failed task costs one review and one demonstration. Quick training (6 tasks) is a few dozen requests; watch the side panel. Use the reference solutions option to train for free.')+
FAQ('My AI did not improve after training.','Check the report: if round 1 failures had no teacher demonstration, the teacher may have failed too (try a higher effort). Very small models (under 7B) improve little; try a bigger base or Marchand Coder. Run training twice: lessons accumulate.')+
FAQ('Can my AI understand videos?','Yes: attach a video and Marchand sends 6 frames with timestamps. Use a vision model, or set a Vision helper in Settings so any AI gets a description.')+
FAQ('Is Marchand free?','Yes. Local models are free. Cloud models (Claude, Grok...) are billed by their companies when you use them.')+
FAQ('Does it work offline?','Yes with local models once downloaded. Downloads, updates and cloud models need internet.')+
FAQ('Do I need a graphics card?','No, but models run several times faster on an NVIDIA card (or Apple Silicon). Without one, choose 3B to 7B models.')+
FAQ('Is it as good as Claude?','No. A local 14B to 32B model is much weaker than Claude on hard tasks. Marchand\'s habits (planning, testing, reviewing, lessons) close part of the gap. Use a cloud model for the hardest jobs.')+
FAQ('Which model is best for coding?','Usually the biggest of qwen2.5-coder, qwen3-coder or devstral that your PC runs comfortably.')+
FAQ('The AI made a mess. How do I undo it?','If the project is under git: <code>git checkout -- .</code> restores all tracked files, and <code>git status</code> shows new files to delete. Always commit before big tasks. Without git, Marchand cannot restore files.')+
FAQ('Can it break my computer?','It can only edit inside the project folder, asks before each change, and blocks destructive commands. Commands you allow still run with your permissions, so read them.')+
FAQ('Why does it ask permission so often?','Safety. Press <b>Always allow</b> for the current run, or turn on auto-approve in Settings for trusted projects.')+
FAQ('How do I make the AI follow my coding style?','Three layers: <b>Instructions</b> (MARCHAND.md) for project rules, a <b>plugin</b> with rules for style everywhere, and <b>lessons</b> from teaching. Then Create your AI to bake them in.')+
FAQ('How many lessons should I have?','10 to 40 good ones. Only about 1,800 characters of lessons are used per conversation, so keep them short and delete duplicates.')+
FAQ('Can Claude and my local model work together?','Yes: Claude as the teacher (Training tab), as the reviewer (review pass), or from Claude Desktop calling your local model (Plugins &gt; Claude Desktop).')+
FAQ('What is the "Review pass"?','After the AI changes files and says it is done, a model reads the diff and the original request and lists problems. If it finds any, the AI fixes them first. Up to two rounds.')+
FAQ('What is a context size and which should I pick?','How much the model remembers in one conversation. 16K is right for most; 32K for big projects if you have the RAM; 8K for old PCs.')+
FAQ('Can I use an Ollama on another computer?','Yes. In Settings set the Ollama address to that computer, for example <code>http://192.168.1.20:11434</code>. On that computer start Ollama with the environment variable <code>OLLAMA_HOST=0.0.0.0</code>.')+
FAQ('Can I use my own AI in other apps?','Yes. Anything you create is a normal Ollama model: select its name in any app that supports Ollama.')+
FAQ('Where is my data stored?','In <code>~/.marchand</code> (on Windows: your user folder, <code>.marchand</code>): conversations, settings, lessons, examples, plugins, your AIs list.')+
FAQ('How do I reset everything?','Close Marchand and delete the <code>.marchand</code> folder in your user folder. Models stay in Ollama (delete them in Models &gt; Installed).')+
FAQ('How do I back up my lessons?','Copy <code>lessons.json</code> and <code>examples.jsonl</code> from the <code>.marchand</code> folder.')+
FAQ('Can I teach it a programming language it does not know?','Lessons and examples help with habits and conventions, not deep new knowledge. For a niche language put reference notes in <code>MARCHAND.md</code> or a plugin skill (the AI loads them when needed).')+
FAQ('Why does the Teach button say choose a teacher first?','Training &gt; Teacher needs a cloud model. Add a key in Models &gt; Cloud and local servers first.')+
FAQ('Do thumbs-up examples leave my computer?','No. They are saved locally. They only reach a company if you later run a Teach on them with a cloud teacher or export them yourself.')+
FAQ('Does it support images?','Yes in Chat and Code: attach or paste an image and pick a vision model (for example llama3.2-vision or gemma3). Models without vision ignore images.')+
FAQ('How do I stop a runaway task?','Press the red Stop button or Esc. Denying an approval card also halts that step.')+
FAQ('Can several people use it?','It is built for one person on one computer. It deliberately accepts connections from this computer only.')+
FAQ('Does it work on Mac and Linux?','The app runs on Windows, macOS and Linux (Python 3.9+). The shortcut installer targets Windows and Linux; on macOS start it with <code>python3 app.py</code>.')+
FAQ('Why is the first start slow?','It installs the window component once and Ollama may need to load the model into memory. Later starts are fast.')+
FAQ('How do I report a problem?','Note the exact message, what you clicked, and your model name. The log is <code>~/.marchand/app.log</code> if you started it from the icon.')
}
];

let HS={id:'welcome',q:''};
async function renderHelp(){
  const root=$('#plug');root.innerHTML='';
  const wrap=el('div','hwrap');root.appendChild(wrap);
  const nav=el('div','hnav');const main=el('div','hmain');wrap.append(nav,main);
  const s=el('input');s.placeholder='Search help: "teach", "update", "error 401"...';s.value=HS.q;nav.appendChild(s);
  const list=el('div');nav.appendChild(list);
  function match(t){if(!HS.q)return true;const q=HS.q.toLowerCase();const text=(t.t+' '+t.tags+' '+t.h.replace(/<[^>]+>/g,' ')).toLowerCase();return q.split(/\s+/).every(w=>text.includes(w))}
  function draw(){
    list.innerHTML='';let last='';
    HELP.filter(match).forEach(t=>{if(t.g!==last){list.appendChild(el('div','hgrp',esc(t.g)));last=t.g}
      const d=el('div','hitem'+(t.id===HS.id?' on':''),esc(t.t));d.onclick=()=>{HS.id=t.id;draw();show()};list.appendChild(d)});
    if(!list.children.length)list.appendChild(el('div','note','No topic matches. Try another word.'));
  }
  function show(){
    const t=HELP.find(x=>x.id===HS.id)||HELP[0];main.innerHTML='';main.scrollTop=0;
    main.appendChild(el('div','hgrp',esc(t.g)));main.appendChild(el('h2',null,esc(t.t)));main.appendChild(el('div','hbody',t.h));
    if(t.go&&t.go.length){const bar=el('div','prow');t.go.forEach(([label,key])=>{const b=el('button','btn pri sm',esc(label));b.onclick=()=>HGO[key]();bar.appendChild(b)});main.appendChild(bar)}
    const i=HELP.indexOf(t);const nx=el('div','prow');nx.style.marginTop='24px';
    if(i>0){const p=el('button','btn sm','&larr; '+esc(HELP[i-1].t));p.onclick=()=>{HS.id=HELP[i-1].id;HS.q='';s.value='';draw();show()};nx.appendChild(p)}
    if(i<HELP.length-1){const n=el('button','btn sm','Next: '+esc(HELP[i+1].t)+' &rarr;');n.style.marginLeft='auto';n.onclick=()=>{HS.id=HELP[i+1].id;HS.q='';s.value='';draw();show()};nx.appendChild(n)}
    main.appendChild(nx)}
  s.oninput=()=>{HS.q=s.value;const m=HELP.filter(match);if(m.length&&!m.find(x=>x.id===HS.id)){HS.id=m[0].id;show()}draw()};
  draw();show();
}
